13:// DEVDESK-580, PR4 (DEVDESK-628, phase B): the `access` campaign holds 25
79:		{target: "/repository/docker-proxy/v2/mirror/cached/blobs/sha256:" + strings.Repeat("a", 64), refused: true},
103:		{target: "/repository/docker-hosted/v2/api@sha256/tags/list", refused: true},
package oci

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"strings"
	"time"
)

// registryHTTPClient is swapped by tests that must reach a stand-in for a
// registry by another address.
var registryHTTPClient = &http.Client{
	Timeout:       15 * time.Second,
	CheckRedirect: RefuseOffOriginRedirect,
}

// ErrTagsNextOffOrigin is returned by ListRegistryTagsContext when a page's
// Link rel="next" points to another origin. The list is not returned partial:
// a short list would pass for the whole one.
var ErrTagsNextOffOrigin = errors.New("tag list continues on another origin")

// errInsecureTokenRealm is returned when a Bearer challenge names a token realm
// that is not a safe http(s) URL for the registry: a scheme other than http or
// https (or none), or http behind an https registry.
var errInsecureTokenRealm = errors.New("refusing a token realm that is not a safe http(s) URL for this registry")

const (
	// maxTagPages bounds how many pages of a tag list are followed. A registry
	// that pages (`?n=`, `Link: rel="next"`) answers a page at a time, and one
	// that keeps answering "next" must not hold a caller forever.
	maxTagPages = 100
	// maxTagResponse bounds one page. Docker Hub answers a whole list in one
	// response when no page size is given — measured at 9 125 tags for
	// library/node (§3.2) — so the bound is generous, but it is a bound.
	maxTagResponse = 32 << 20
	// maxTokenResponse bounds a Bearer token endpoint's answer; a token is a
	// few KiB, so a larger body is an error, not a silent cut.
	maxTokenResponse = 1 << 20
)

// StatusSource says which endpoint answered with a non-success status.
type StatusSource int

const (
	// SourceRegistry is the registry's v2 API.
	SourceRegistry StatusSource = iota
	// SourceToken is the Bearer token endpoint.
	SourceToken
	// SourceManagementAPI is a registry manager's own REST API (Nexus
	// /service/rest), not the distribution v2 API.
	SourceManagementAPI
)

// StatusError is a registry, token or management API endpoint answering with a
// non-success status. Failures that are not a status (unreadable body, missing
// realm, no token field) are plain errors.
type StatusError struct {
	Code   int
	Source StatusSource
	// Challenge is the Www-Authenticate header of a 401 whose challenge is not
	// Bearer; empty otherwise.
	Challenge string
	// unexpectedChallenge tells that 401 apart from a 401 answered after a
	// token exchange, so Error() keeps both historical messages.
	unexpectedChallenge bool
}

// Error returns the message the plain errors carried before the type existed.
func (e *StatusError) Error() string {
	switch {
	case e.Source == SourceToken:
		return fmt.Sprintf("token endpoint returned %d", e.Code)
	case e.Source == SourceManagementAPI:
		return fmt.Sprintf("management API returned %d", e.Code)
	case e.unexpectedChallenge:
		return fmt.Sprintf("unexpected auth challenge: %s", e.Challenge)
	}
	return fmt.Sprintf("registry returned %d", e.Code)
}

// ListRegistryTags lists the tags of a repository through the registry's v2 API.
//
// apiURL is the API base (see the browser's registryAPIURL). Credentials, when
// given, go as Basic auth and, on a 401 that names a Bearer realm, to that
// realm's token endpoint — the flow Docker Hub and most hosted registries use.
// The token is kept for the following pages.
//
// The list is followed across pages: whatever a registry caps a response at,
// and Docker Hub does not, a repository with more tags than one page holds is
// returned whole. This is the one tag lister that speaks the Bearer flow; the
// template client's ListTags (Client.ListTags) reads a registry the user
// configured for templates and only ever sends Basic auth.
func ListRegistryTags(apiURL, repo, username, password string) ([]string, error) {
	return ListRegistryTagsContext(context.Background(), apiURL, repo, username, password)
}

// ListRegistryTagsContext is ListRegistryTags bound to ctx: a cancelled or
// expired context stops the walk, including a request in flight, and the
// returned error wraps the context's error. A context already done sends
// nothing. registryHTTPClient's own timeout still applies per request; when
// both expire, whichever comes first ends the request, and either way the
// error satisfies errors.Is(err, context.DeadlineExceeded).
func ListRegistryTagsContext(ctx context.Context, apiURL, repo, username, password string) ([]string, error) {
	next := fmt.Sprintf("%s/v2/%s/tags/list", strings.TrimSuffix(apiURL, "/"), repo)
	var (
		tags  []string
		token string
	)
	for page := 0; next != ""; page++ {
		if page == maxTagPages {
			return nil, fmt.Errorf("tag list of %s is longer than %d pages", repo, maxTagPages)
		}
		body, link, usedToken, err := registryGETContext(ctx, next, username, password, token)
		if err != nil {
			return nil, err
		}
		token = usedToken
		var result struct {
			Tags []string `json:"tags"`
		}
		if err := json.Unmarshal(body, &result); err != nil {
			return nil, fmt.Errorf("decode tags response: %w", err)
		}
		tags = append(tags, result.Tags...)
		current := next
		if next = resolveNext(current, link); next != "" && !sameOrigin(current, next) {
			// Never send credentials to another origin, and never pass a
			// partial list off as the whole one. Only the host is named.
			return nil, fmt.Errorf("%w (%s)", ErrTagsNextOffOrigin, hostOf(next))
		}
	}
	return tags, nil
}

// registryGET performs a GET, answering a Bearer challenge once. It returns the
// body, the Link header, and the token to send on the following requests.
func registryGET(rawURL, username, password, token string) (body []byte, link, usedToken string, err error) {
	return registryGETContext(context.Background(), rawURL, username, password, token)
}

// registryGETContext is registryGET bound to ctx.
func registryGETContext(ctx context.Context, rawURL, username, password, token string) (body []byte, link, usedToken string, err error) {
	resp, token, err := registryDoContext(ctx, http.MethodGet, rawURL, "", username, password, token)
	if err != nil {
		return nil, "", token, err
	}
	defer func() { _ = resp.Body.Close() }()
	if resp.StatusCode != http.StatusOK {
		return nil, "", token, &StatusError{Code: resp.StatusCode, Source: SourceRegistry}
	}
	body, err = io.ReadAll(io.LimitReader(resp.Body, maxTagResponse))
	return body, resp.Header.Get("Link"), token, err
}

// registryDo sends one request, answering a Bearer challenge once. The caller
// closes the response body and reads the status.
func registryDo(method, rawURL, accept, username, password, token string) (*http.Response, string, error) {
	return registryDoContext(context.Background(), method, rawURL, accept, username, password, token)
}

// registryDoContext is registryDo bound to ctx.
func registryDoContext(ctx context.Context, method, rawURL, accept, username, password, token string) (*http.Response, string, error) {
	resp, err := doRequestContext(ctx, method, rawURL, accept, username, password, token)
	if err != nil {
		return nil, token, err
	}
	if resp.StatusCode != http.StatusUnauthorized {
		return resp, token, nil
	}
	challenge := resp.Header.Get("Www-Authenticate")
	_ = resp.Body.Close()
	if !strings.HasPrefix(challenge, "Bearer ") {
		return nil, token, &StatusError{Code: http.StatusUnauthorized, Source: SourceRegistry, Challenge: challenge, unexpectedChallenge: true}
	}
	// exchangeBearerTokenContext refuses an insecure realm itself, before any request.
	token, err = exchangeBearerTokenContext(ctx, rawURL, challenge[7:], username, password)
	if err != nil {
		return nil, "", err
	}
	if resp, err = doRequestContext(ctx, method, rawURL, accept, "", "", token); err != nil {
		return nil, token, fmt.Errorf("%s (retry) %s: %w", method, RedactURL(rawURL), err)
	}
	return resp, token, nil
}

// doRequest sends one request: a bearer token when there is one, Basic auth
// when there are credentials and no token.
func doRequest(method, rawURL, accept, username, password, token string) (*http.Response, error) {
	return doRequestContext(context.Background(), method, rawURL, accept, username, password, token)
}

// doRequestContext is doRequest bound to ctx; a context already done sends
// nothing.
func doRequestContext(ctx context.Context, method, rawURL, accept, username, password, token string) (*http.Response, error) {
	req, err := http.NewRequestWithContext(ctx, method, rawURL, nil)
	if err != nil {
		return nil, buildRequestError("build request", rawURL, err)
	}
	if accept != "" {
		req.Header.Set("Accept", accept)
	}
	switch {
	case token != "":
		req.Header.Set("Authorization", "Bearer "+token)
	case username != "" && password != "":
		req.SetBasicAuth(username, password)
	}
	resp, err := registryHTTPClient.Do(req)
	if err != nil {
		return nil, fmt.Errorf("%s %s: %w", method, RedactURL(rawURL), StripRedirectTarget(err))
	}
	return resp, nil
}

// buildRequestError is the error of a request that could not be built. The
// *url.Error net/http returns holds the raw URL, password included, so only the
// cause and the redacted URL are kept.
func buildRequestError(what, rawURL string, err error) error {
	var ue *url.Error
	if errors.As(err, &ue) {
		err = ue.Err
	}
	return fmt.Errorf("%s for %s: %w", what, RedactURL(rawURL), err)
}

// manifestAccept lists every manifest kind a tag can point to. A multi-platform
// tag is an index (or a Docker manifest list), and its digest is the one `docker
// pull` records in RepoDigests; asking for a single-platform manifest only
// would make the registry convert or refuse, and the digests would not match.
var manifestAccept = strings.Join([]string{
	"application/vnd.oci.image.index.v1+json",
	"application/vnd.docker.distribution.manifest.list.v2+json",
	"application/vnd.oci.image.manifest.v1+json",
	"application/vnd.docker.distribution.manifest.v2+json",
}, ", ")

// ManifestDigest returns the digest a tag currently points to, from the
// registry's Docker-Content-Digest header.
//
// It is a HEAD request: Docker Hub does not count a HEAD against the pull rate
// limit, and nothing but the header is needed.
func ManifestDigest(apiURL, repo, tag, username, password string) (string, error) {
	rawURL := fmt.Sprintf("%s/v2/%s/manifests/%s", strings.TrimSuffix(apiURL, "/"), repo, url.PathEscape(tag))
	resp, _, err := registryDo(http.MethodHead, rawURL, manifestAccept, username, password, "")
	if err != nil {
		return "", err
	}
	_ = resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		return "", fmt.Errorf("registry returned %d for %s:%s", resp.StatusCode, repo, tag)
	}
	digest := resp.Header.Get("Docker-Content-Digest")
	if digest == "" {
		return "", fmt.Errorf("registry gave no digest for %s:%s", repo, tag)
	}
	return digest, nil
}

// RegistryAPIBase is the v2 API root of a registry named in an image reference:
// Docker Hub has its own host, a local registry is reached over plain HTTP, and
// everything else over HTTPS. An empty registry is Docker Hub.
func RegistryAPIBase(registry string) string {
	switch {
	case registry == "":
		return "https://registry-1.docker.io"
	case strings.HasPrefix(registry, "localhost") || strings.HasPrefix(registry, "127.0.0.1"):
		return "http://" + registry
	}
	return "https://" + registry
}

// hostOf is the host of rawURL, or "" when it does not parse.
func hostOf(rawURL string) string {
	u, err := url.Parse(rawURL)
	if err != nil {
		return ""
	}
	return u.Host
}

// resolveNext is the URL a Link header's rel="next" points to, resolved against
// the page it came with — registries send it as a path — or "" when there is
// none. A next link that leads back to the page just read ends the walk rather
// than looping on it.
func resolveNext(current, link string) string {
	for _, part := range strings.Split(link, ",") {
		target, rel, ok := strings.Cut(strings.TrimSpace(part), ";")
		if !ok || !strings.Contains(rel, `rel="next"`) {
			continue
		}
		target = strings.Trim(strings.TrimSpace(target), "<>")
		base, err := url.Parse(current)
		if err != nil {
			return ""
		}
		ref, err := url.Parse(target)
		if err != nil {
			return ""
		}
		if next := base.ResolveReference(ref).String(); next != current {
			return next
		}
	}
	return ""
}

// exchangeBearerToken fetches a bearer token from the registry's token endpoint.
func exchangeBearerToken(registryURL, challenge, username, password string) (string, error) {
	return exchangeBearerTokenContext(context.Background(), registryURL, challenge, username, password)
}

// checkTokenRealm refuses, before any request to it, a Bearer realm that is
// neither http nor https (a relative realm included). It also refuses an http
// realm when the registry is https or cannot be parsed, whatever the
// credentials: the realm would otherwise receive them (or a token request) in
// clear. A missing or unparsable realm passes: exchangeBearerTokenContext
// reports those. The error names the realm's host only, never its userinfo,
// path or query.
func checkTokenRealm(registryURL, challenge string) error {
	realm, ok := parseBearerChallenge(challenge)["realm"]
	if !ok {
		return nil
	}
	u, err := url.Parse(realm)
	if err != nil {
		return nil
	}
	reg, _ := url.Parse(registryURL)
	switch {
	case u.Scheme == "https":
		return nil
	case u.Scheme == "http" && reg != nil && reg.Scheme != "https":
		return nil
	case u.Hostname() == "":
		return errInsecureTokenRealm
	}
	return fmt.Errorf("%w (%s)", errInsecureTokenRealm, u.Host)
}

// exchangeBearerTokenContext is exchangeBearerToken bound to ctx. It applies
// checkTokenRealm itself, so no caller reaches an insecure realm by skipping
// registryDoContext; registryURL is the registry that sent the challenge.
func exchangeBearerTokenContext(ctx context.Context, registryURL, challenge, username, password string) (string, error) {
	if err := checkTokenRealm(registryURL, challenge); err != nil {
		return "", err
	}
	u, err := tokenEndpoint(challenge)
	if err != nil {
		return "", err
	}
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, u, nil)
	if err != nil {
		return "", buildRequestError("build token request", u, err)
	}
	if username != "" && password != "" {
		req.SetBasicAuth(username, password)
	}
	resp, err := registryHTTPClient.Do(req)
	if err != nil {
		return "", fmt.Errorf("fetch token: %w", StripRedirectTarget(err))
	}
	defer func() { _ = resp.Body.Close() }()
	if resp.StatusCode != http.StatusOK {
		return "", &StatusError{Code: resp.StatusCode, Source: SourceToken}
	}
	return readToken(resp.Body)
}

// tokenEndpoint is the URL of the token request a Bearer challenge asks for: its
// realm, with the service and scope it names as the query.
func tokenEndpoint(challenge string) (string, error) {
	params := parseBearerChallenge(challenge)
	realm, ok := params["realm"]
	if !ok {
		return "", fmt.Errorf("bearer challenge missing realm")
	}
	u, err := url.Parse(realm)
	if err != nil {
		// The raw realm may hold a userinfo or a signed query: only the cause stays.
		var ue *url.Error
		if errors.As(err, &ue) {
			err = ue.Err
		}
		return "", fmt.Errorf("parse realm: %w", err)
	}
	q := u.Query()
	if s, ok := params["service"]; ok {
		q.Set("service", s)
	}
	if s, ok := params["scope"]; ok {
		q.Set("scope", s)
	}
	u.RawQuery = q.Encode()
	return u.String(), nil
}

// readToken reads a token endpoint's answer, at most maxTokenResponse bytes, and
// returns the token it holds.
func readToken(body io.Reader) (string, error) {
	data, err := io.ReadAll(io.LimitReader(body, maxTokenResponse+1))
	if err != nil {
		return "", fmt.Errorf("read token response: %w", err)
	}
	if len(data) > maxTokenResponse {
		return "", fmt.Errorf("token response over %d bytes", maxTokenResponse)
	}
	var result struct {
		Token       string `json:"token"`
		AccessToken string `json:"access_token"`
	}
	if err := json.Unmarshal(data, &result); err != nil {
		return "", fmt.Errorf("decode token response: %w", err)
	}
	if result.Token != "" {
		return result.Token, nil
	}
	if result.AccessToken != "" {
		return result.AccessToken, nil
	}
	return "", fmt.Errorf("token response contained no token field")
}

// parseBearerChallenge parses the value portion of a Www-Authenticate: Bearer header.
// Example: `realm="https://auth.docker.io/token",service="registry.docker.io"`
func parseBearerChallenge(s string) map[string]string {
	params := make(map[string]string)
	for _, part := range strings.Split(s, ",") {
		part = strings.TrimSpace(part)
		idx := strings.IndexByte(part, '=')
		if idx < 0 {
			continue
		}
		key := strings.TrimSpace(part[:idx])
		val := strings.Trim(strings.TrimSpace(part[idx+1:]), `"`)
		params[key] = val
	}
	return params
}

// Package fakenexus replays recorded Nexus answers over loopback HTTP. It is the
// only package of the fixture tree that imports testing: the recorder and the
// nexus-bench binary stay free of it (nexusfixture itself must not import it).
// Import it from _test.go files only.
package fakenexus

import (
	"bytes"
	"encoding/json"
	"maps"
	"net/http"
	"net/http/httptest"
	"net/url"
	"regexp"
	"slices"
	"strconv"
	"strings"
	"sync"
	"testing"

	"github.com/anthnel/devdesk/internal/nexusfixture"
)

// Password is the password the fake accepts for every account.
const Password = "REDACTED"

// BadPassword is the public wrong password that, with the user "admin", makes the
// fake identify the request as the BadCredentials identity.
const BadPassword = "REDACTED"

// tokenPrefix starts the token the fake serves: "fixture-token-<identity>". A
// request carrying it as a Bearer credential is identified as that identity.
const tokenPrefix = "fixture-token-"

// User returns the user name an identity authenticates as; anonymous has none.
func User(id nexusfixture.Identity) string {
	switch id {
	case nexusfixture.Admin, nexusfixture.BadCredentials:
		return "admin"
	case nexusfixture.Pull:
		return "bench-pull"
	default:
		return ""
	}
}

// unknownCredentials names the identity of a request whose credentials are not
// one of the bench's accounts (wrong password, unknown user, Bearer...).
const unknownCredentials = "unrecognized credentials"

// who is what a request authenticates as: an account, and whether it presented
// it as a Bearer token (a recorded "Bearer <redacted>") rather than Basic or nothing.
type who struct {
	id     nexusfixture.Identity
	bearer bool
}

// route is one recorded exchange, with the fixture it comes from.
type route struct {
	fixture  string
	identity nexusfixture.Identity
	bearer   bool // the exchange was recorded with a Bearer Authorization
	ex       nexusfixture.Exchange
}

// recordedBearer reports whether a recorded exchange carries a Bearer Authorization.
func recordedBearer(ex nexusfixture.Exchange) bool {
	scheme, _, _ := strings.Cut(ex.RequestHeader.Get("Authorization"), " ")
	return strings.EqualFold(scheme, "Bearer")
}

// Server answers the recorded exchanges, one httptest server per recorded Host.
type Server struct {
	t testing.TB

	mu       sync.Mutex // guards hits and the fields set by New
	hits     map[string]int
	urls     map[string]string // recorded Host -> fake server URL
	servers  []*httptest.Server
	rewriter *strings.Replacer
}

// New starts one loopback server for each Host the fixtures were recorded on and
// closes them with t. A request no fixture answers gets a 501 and a t.Errorf
// (never a Fatalf: the handler does not run on the test goroutine).
func New(t testing.TB, fixtures ...nexusfixture.Fixture) *Server {
	t.Helper()
	s := &Server{t: t, hits: map[string]int{}, urls: map[string]string{}}

	routes := map[string][]route{}
	seen := map[exchangeKey]string{} // exchange -> the fixture that recorded it
	var hosts []string
	for _, f := range fixtures {
		for _, ex := range f.Exchanges {
			if _, ok := routes[ex.Host]; !ok {
				hosts = append(hosts, ex.Host)
				routes[ex.Host] = nil
			}
			if !s.accept(f, ex, seen) {
				continue
			}
			routes[ex.Host] = append(routes[ex.Host], route{fixture: f.Name, identity: f.Identity, bearer: recordedBearer(ex), ex: ex})
		}
	}

	s.mu.Lock()
	defer s.mu.Unlock()
	var pairs []string
	for _, host := range hosts {
		srv := httptest.NewServer(s.handler(routes[host]))
		s.servers = append(s.servers, srv)
		s.urls[host] = srv.URL
		pairs = append(pairs, "http://"+host, srv.URL)
	}
	s.rewriter = strings.NewReplacer(pairs...)
	t.Cleanup(func() {
		for _, srv := range s.servers {
			srv.Close()
		}
	})
	return s
}

// exchangeKey is what a request is matched on: two exchanges sharing it cannot
// both be replayed. The same request with and without a Bearer token (the 401 and
// its retry in a Bearer flow) are two exchanges.
type exchangeKey struct {
	host, method, target string
	identity             nexusfixture.Identity
	bearer               bool
}

// accept reports whether an exchange can be replayed faithfully, and fails the
// test (naming the fixture) when it cannot: a Status of 0 (the handler would
// panic on it), a stub with no faithful stand-in, or a second exchange for the
// same host, method, target, identity and Bearer-or-not, checked exchange by
// exchange. A refused exchange is not served.
func (s *Server) accept(f nexusfixture.Fixture, ex nexusfixture.Exchange, seen map[exchangeKey]string) bool {
	ok := true
	if ex.Status == 0 {
		s.t.Errorf("fakenexus: fixture %s: %s %s on %s has no status", f.Name, ex.Method, ex.Target, ex.Host)
		ok = false
	}
	if _, valid := bodyOf(ex); !valid {
		s.t.Errorf("fakenexus: fixture %s: %s %s: stub %q has no faithful stand-in (only %q and an HTML summary with a title do)",
			f.Name, ex.Method, ex.Target, ex.Stub, emptyStub)
		ok = false
	}
	key := exchangeKey{host: ex.Host, method: ex.Method, target: ex.Target, identity: f.Identity, bearer: recordedBearer(ex)}
	if first, dup := seen[key]; dup {
		s.t.Errorf("fakenexus: fixtures %s and %s both record %s %s on %s as %s",
			first, f.Name, ex.Method, ex.Target, ex.Host, f.Identity)
		ok = false
	} else {
		seen[key] = f.Name
	}
	return ok
}

// URL returns the base URL of the fake server standing for a recorded Host,
// such as "127.0.0.1:30481".
func (s *Server) URL(recordedHost string) string {
	s.mu.Lock()
	defer s.mu.Unlock()
	u, ok := s.urls[recordedHost]
	if !ok {
		s.t.Errorf("fakenexus: no fixture was recorded on host %s", recordedHost)
	}
	return u
}

// Hits counts the requests the named fixture answered, tolerated ones included.
func (s *Server) Hits(fixtureName string) int {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.hits[fixtureName]
}

func (s *Server) handler(routes []route) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		id, known := identify(r)
		if known {
			if rt, ok := s.match(routes, r.Method, r.URL.RequestURI(), id); ok {
				s.replay(w, rt)
				return
			}
		}
		label := unknownCredentials
		if known {
			label = string(id.id)
		}
		s.t.Errorf("no recorded answer for %s %s as %s", r.Method, r.URL.RequestURI(), label)
		http.Error(w, "no recorded answer", http.StatusNotImplemented)
	})
}

// identify reads the account a request authenticates as: nothing is anonymous, a
// Bearer token is the identity it names (tokenPrefix), Basic with Password is the
// account of that user, and Basic with BadPassword and the user "admin" is
// BadCredentials. known is false when the credentials are none of these: that
// never matches a recording.
func identify(r *http.Request) (w who, known bool) {
	header := r.Header.Get("Authorization")
	if header == "" {
		return who{id: nexusfixture.Anonymous}, true
	}
	if token, ok := strings.CutPrefix(header, "Bearer "); ok {
		for _, id := range []nexusfixture.Identity{nexusfixture.Admin, nexusfixture.Pull, nexusfixture.Anonymous} {
			if token == tokenOf(id) {
				return who{id: id, bearer: true}, true
			}
		}
		return who{}, false
	}
	user, pass, ok := r.BasicAuth()
	switch {
	case ok && pass == Password:
		for _, id := range []nexusfixture.Identity{nexusfixture.Admin, nexusfixture.Pull} {
			if user == User(id) {
				return who{id: id}, true
			}
		}
	case ok && pass == BadPassword && user == User(nexusfixture.BadCredentials):
		return who{id: nexusfixture.BadCredentials}, true
	}
	return who{}, false
}

// tokenOf is the token the fake serves to an identity.
func tokenOf(id nexusfixture.Identity) string { return tokenPrefix + string(id) }

// match picks the exchange recorded for the method, target and credentials: the
// exact target first (a token request on its decoded query), then the catalog
// tolerance.
func (s *Server) match(routes []route, method, target string, w who) (route, bool) {
	for _, rt := range routes {
		if rt.identity == w.id && rt.bearer == w.bearer && rt.ex.Method == method && s.sameTarget(rt.ex.Target, target) {
			return rt, true
		}
	}
	if method != http.MethodGet {
		return route{}, false
	}
	return matchCatalogTolerance(routes, target, w)
}

// sameTarget compares a recorded target with a requested one: equal, or, for a
// token request, the same path and the same decoded query once the recorded
// "http://<host>" of each value is pointed at the fake that stands for it (the
// client built "service" from a realm the fake had rewritten). A token request
// that still names the recorded address is not the one the fake handed out.
func (s *Server) sameTarget(recorded, requested string) bool {
	recPath, recQuery, _ := strings.Cut(recorded, "?")
	path, query, _ := strings.Cut(requested, "?")
	if !nexusfixture.IsTokenPath(recPath) {
		return recorded == requested
	}
	if path != recPath {
		return false
	}
	want, err := url.ParseQuery(recQuery)
	if err != nil {
		return false
	}
	got, err := url.ParseQuery(query)
	if err != nil {
		return false
	}
	for _, values := range want {
		for i, v := range values {
			values[i] = s.rewrite(v)
		}
	}
	return maps.EqualFunc(want, got, slices.Equal[[]string])
}

// rewrite points the recorded host of a value at its fake server.
func (s *Server) rewrite(v string) string {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.rewriter.Replace(v)
}

// toleratedN is the only n (what DevDesk asks) tolerated without "last".
const toleratedN = 1000

// matchCatalogTolerance lets "GET P?n=1000" (no "last") be answered by a fixture
// recorded as "GET P" without a query, provided that answer is a 200 with no Link
// and lists at most 1000 names: one page holds the whole catalog, as with n=1000.
// Any other n is not measured and is not tolerated.
//
// Measured: n=1000 and no n answer identically on the group connector
// (page-group-n1000--admin and catalog-group-connector-30482--admin), and, since
// DEVDESK-580, on the hosted and proxy catalogs by path and on the 404 of the root
// and of the group path (catalog-*-n1000--*, for the three identities); all pinned
// by TestTheCatalogToleranceHasMeasuredGround. Those exact fixtures win over the
// tolerance. For the other targets (the "/repository/<name>/v2/" paths, the group
// connector's pull and anonymous identities) it stays an inference: only no-n and
// n=2 were measured there. A 404 is never tolerated, so "?n=1000" on a target with
// no exact fixture stays unmatched.
func matchCatalogTolerance(routes []route, target string, w who) (route, bool) {
	path, rawQuery, _ := strings.Cut(target, "?")
	query, err := url.ParseQuery(rawQuery)
	if err != nil || len(query) != 1 || len(query["n"]) != 1 {
		return route{}, false
	}
	n, err := strconv.Atoi(query.Get("n"))
	if err != nil || n != toleratedN {
		return route{}, false
	}
	for _, rt := range routes {
		ex := rt.ex
		if rt.identity != w.id || rt.bearer != w.bearer || ex.Method != http.MethodGet || ex.Target != path ||
			ex.Status != http.StatusOK || ex.Header.Get("Link") != "" {
			continue
		}
		var catalog struct {
			Repositories []string `json:"repositories"`
		}
		if json.Unmarshal(ex.Body, &catalog) == nil && catalog.Repositories != nil && len(catalog.Repositories) <= n {
			return rt, true
		}
	}
	return route{}, false
}

// rewrittenHeaders carry an address of the recorded host; they are pointed at the
// fake server of that host. A body is data and is never rewritten.
var rewrittenHeaders = []string{"Link", "Location", "Www-Authenticate"}

// replay writes the recorded status, headers and body. Content-Length is
// recomputed from the body actually served, since a stub is shorter than the
// answer it summarises; a HEAD answer has no body, so its recorded Content-Length
// (the size of the answer a GET would give) is kept. A token answer has its
// "<redacted>" replaced by the token of the identity it was recorded for.
func (s *Server) replay(w http.ResponseWriter, rt route) {
	s.mu.Lock()
	s.hits[rt.fixture]++
	rewriter := s.rewriter
	s.mu.Unlock()

	ex := rt.ex
	h := w.Header()
	for name, values := range ex.Header {
		if name == "Content-Length" {
			continue
		}
		rewrite := contains(rewrittenHeaders, name)
		for _, v := range values {
			if rewrite {
				v = rewriter.Replace(v)
			}
			h.Add(name, v)
		}
	}
	if len(ex.Header.Values("Content-Type")) == 0 {
		h["Content-Type"] = nil // a nil value stops Go from sniffing one
	}
	body, _ := bodyOf(ex) // a stub without a stand-in was refused by New
	if path, _, _ := strings.Cut(ex.Target, "?"); nexusfixture.IsTokenPath(path) {
		body = bytes.ReplaceAll(body, []byte("<redacted>"), []byte(tokenOf(rt.identity)))
	}
	head := ex.Method == http.MethodHead
	length := strconv.Itoa(len(body))
	if head {
		length = ex.Header.Get("Content-Length")
	}
	if length != "" {
		h.Set("Content-Length", length)
	}
	w.WriteHeader(ex.Status)
	if !head {
		_, _ = w.Write(body)
	}
}

var htmlTitle = regexp.MustCompile(`, (<title>.*</title>)>$`)

// emptyStub is the stub of a recorded empty body.
const emptyStub = "<empty body>"

// bodyOf is the body to serve: the recorded one, or a stand-in for a summarised
// body. Only two stubs have a faithful one: an empty body and an HTML page that
// kept its title. valid is false for any other stub.
func bodyOf(ex nexusfixture.Exchange) (body []byte, valid bool) {
	switch {
	case ex.Stub == "":
		return ex.Body, true
	case ex.Stub == emptyStub:
		return nil, true
	case strings.HasPrefix(ex.Stub, "<HTML body omitted:"):
		if m := htmlTitle.FindStringSubmatch(ex.Stub); m != nil {
			return []byte("<html><head>" + m[1] + "</head></html>"), true
		}
	}
	return nil, false
}

func contains(list []string, s string) bool {
	for _, v := range list {
		if v == s {
			return true
		}
	}
	return false
}

