func TestURLsDevDeskCallsAreTheMeasuredOnes(t *testing.T) {
	for _, mode := range routingModes() {
		for _, id := range measuredIdentities {
			t.Run(mode.name+", "+string(id), func(t *testing.T) {
				campaign, catalogName := mode.catalog(id)
